import java.lang.Math;
import java.util.HashMap;
import java.util.Map;

// ==================== 常量配置区 ====================
class GameConstants {
    public static final int GAME_BASE_HEALTH = 500;
    public static final int BARRACK_HEALTH = 100;
    public static final int WAR_FACTORY_HEALTH = 100;

    public static final int RIFLE_SOLDIER_HEALTH = 50;
    public static final int RIFLE_SOLDIER_ATTACK_POWER = 5;
    public static final int RIFLE_SOLDIER_ATTACK_RANGE = 5;

    public static final int RPG_SOLDIER_HEALTH = 50;
    public static final int RPG_SOLDIER_ATTACK_POWER = 10;
    public static final int RPG_SOLDIER_ATTACK_RANGE = 10;

    public static final int DOG_HEALTH = 50;
    public static final int DOG_ATTACK_POWER = 5;
    public static final int DOG_ATTACK_RANGE = 5;

    public static final int MEDIUM_TANK_HEALTH = 100;
    public static final int MEDIUM_TANK_ATTACK_POWER = 10;
    public static final int MEDIUM_TANK_ATTACK_RANGE = 10;

    public static final int HEAVY_TANK_HEALTH = 200;
    public static final int HEAVY_TANK_ATTACK_POWER = 20;
    public static final int HEAVY_TANK_ATTACK_RANGE = 10;
}

enum EnumObjectType {
    barrack, warFactory, rifleSoldier, RPGSoldier, dog, mediumTank, heavyTank
}

// ==================== 抽象基类：游戏对象（带Map统计） ====================
abstract class GameObject {
    protected int x, y, health, attackRange, attackPower;
    protected boolean countedAsDead = false;

    // 全局统计Map：类名 -> [生存数量, 死亡数量]
    protected static Map<String, int[]> globalStats = new HashMap<>();
    protected String className;

    public GameObject(int x, int y, int health) {
        this.x = x;
        this.y = y;
        this.health = health;
        this.attackRange = 0;
        this.attackPower = 0;
        this.className = this.getClass().getSimpleName();
        onCreated();
    }

    // 创建时更新统计
    protected void onCreated() {
        globalStats.putIfAbsent(className, new int[]{0, 0});
        globalStats.get(className)[0]++;
    }

    // 死亡时更新统计
    protected void onDestroyed() {
        if (globalStats.containsKey(className)) {
            globalStats.get(className)[0]--;
            globalStats.get(className)[1]++;
        }
    }

    public int getX() { return x; }
    public int getY() { return y; }
    public int getHealth() { return health; }
    public boolean isDestroyed() { return health <= 0; }

    protected double distanceTo(GameObject other) {
        int dx = this.x - other.x, dy = this.y - other.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    protected boolean canAttack(GameObject target) {
        return distanceTo(target) <= this.attackRange;
    }

    protected void takeDamage(int damage) {
        this.health -= damage;
        onDamageTaken();
    }

    protected void onDamageTaken() {
        if (isDestroyed() && !countedAsDead) {
            onDestroyed();
            countedAsDead = true;
        }
    }

    // 全局统计查询方法
    public static int getLivingCount(String className) {
        return globalStats.getOrDefault(className, new int[]{0, 0})[0];
    }

    public static int getDeadedCount(String className) {
        return globalStats.getOrDefault(className, new int[]{0, 0})[1];
    }

    public static Map<String, int[]> getAllStats() {
        return new HashMap<>(globalStats);
    }

    public abstract void move(int dx, int dy);
}

// ==================== 抽象类：建筑物 ====================
abstract class Building extends GameObject {
    public Building(int x, int y, int health) { super(x, y, health); }
    public void move(int dx, int dy) {}
}

// ==================== 抽象类：可移动攻击单位 ====================
abstract class MobileUnit extends GameObject {
    public MobileUnit(int x, int y, int health, int range, int power) {
        super(x, y, health);
        this.attackRange = range;
        this.attackPower = power;
    }

    public void move(int dx, int dy) { this.x += dx; this.y += dy; }

    public void attack(GameObject target) {
        if (!canAttack(target) || target.isDestroyed()) return;
        target.takeDamage(calculateDamage(target));
    }

    protected int calculateDamage(GameObject target) { return this.attackPower; }
}

// ==================== 具体类：中型坦克 ====================
class MediumTank extends MobileUnit {
    public MediumTank(int x, int y) {
        super(x, y, GameConstants.MEDIUM_TANK_HEALTH, 
              GameConstants.MEDIUM_TANK_ATTACK_RANGE, 
              GameConstants.MEDIUM_TANK_ATTACK_POWER);
    }
}

// ==================== 具体类：重型坦克 ====================
class HeavyTank extends MobileUnit {
    public HeavyTank(int x, int y) {
        super(x, y, GameConstants.HEAVY_TANK_HEALTH, 
              GameConstants.HEAVY_TANK_ATTACK_RANGE, 
              GameConstants.HEAVY_TANK_ATTACK_POWER);
    }
}

// ==================== 抽象类：士兵（继承MobileUnit） ====================
abstract class Soldier extends MobileUnit {
    public Soldier(int x, int y, int health, int range, int power) {
        super(x, y, health, range, power);
    }

    @Override
    protected int calculateDamage(GameObject target) {
        return calculateSoldierDamage(target);
    }

    protected abstract int calculateSoldierDamage(GameObject target);

    // 通过类名从全局Map获取士兵统计
    public static int getLivingSoldierCount() {
        return GameObject.getLivingCount("RifleSoldier")
             + GameObject.getLivingCount("RPGSoldier")
             + GameObject.getLivingCount("Dog");
    }

    public static int getDeadedSoldierCount() {
        return GameObject.getDeadedCount("RifleSoldier")
             + GameObject.getDeadedCount("RPGSoldier")
             + GameObject.getDeadedCount("Dog");
    }
}

// ==================== 具体类：步枪兵 ====================
class RifleSoldier extends Soldier {
    public RifleSoldier(int x, int y) {
        super(x, y, GameConstants.RIFLE_SOLDIER_HEALTH, 
              GameConstants.RIFLE_SOLDIER_ATTACK_RANGE, 
              GameConstants.RIFLE_SOLDIER_ATTACK_POWER);
    }

    protected int calculateSoldierDamage(GameObject target) {
        return (target instanceof Dog) ? target.getHealth() : this.attackPower;
    }
}

// ==================== 具体类：火箭兵 ====================
class RPGSoldier extends Soldier {
    public RPGSoldier(int x, int y) {
        super(x, y, GameConstants.RPG_SOLDIER_HEALTH, 
              GameConstants.RPG_SOLDIER_ATTACK_RANGE, 
              GameConstants.RPG_SOLDIER_ATTACK_POWER);
    }

    protected int calculateSoldierDamage(GameObject target) {
        return this.attackPower;
    }
}

// ==================== 具体类：军犬 ====================
class Dog extends Soldier {
    public Dog(int x, int y) {
        super(x, y, GameConstants.DOG_HEALTH, 
              GameConstants.DOG_ATTACK_RANGE, 
              GameConstants.DOG_ATTACK_POWER);
    }

    protected int calculateSoldierDamage(GameObject target) {
        return (target instanceof Soldier && !(target instanceof Dog)) 
               ? target.getHealth() : this.attackPower;
    }
}

// ==================== 具体类：兵营 ====================
class Barrack extends Building {
    public Barrack(int x, int y) { super(x, y, GameConstants.BARRACK_HEALTH); }

    // 训练士兵和军犬
    public Soldier train(EnumObjectType type) {
        switch (type) {
            case rifleSoldier: return new RifleSoldier(this.x, this.y);
            case RPGSoldier: return new RPGSoldier(this.x, this.y);
            case dog: return new Dog(this.x, this.y);
            default: throw new IllegalArgumentException("兵营无法训练: " + type);
        }
    }
}

// ==================== 具体类：兵工厂 ====================
class WarFactory extends Building {
    public WarFactory(int x, int y) { super(x, y, GameConstants.WAR_FACTORY_HEALTH); }

    // 生产坦克
    public MobileUnit produce(EnumObjectType type) {
        switch (type) {
            case mediumTank: return new MediumTank(this.x, this.y);
            case heavyTank: return new HeavyTank(this.x, this.y);
            default: throw new IllegalArgumentException("兵工厂无法生产: " + type);
        }
    }
}

// ==================== 具体类：玩家基地 ====================
class GameBase extends Building {
    public GameBase(int x, int y) { super(x, y, GameConstants.GAME_BASE_HEALTH); }

    public static GameBase createGameBase(int x, int y) {
        return new GameBase(x, y);
    }

    // 建造兵营和兵工厂
    public Building building(EnumObjectType type, int x, int y) {
        switch (type) {
            case barrack: return new Barrack(x, y);
            case warFactory: return new WarFactory(x, y);
            default: throw new IllegalArgumentException("无法建造: " + type);
        }
    }
}

// ==================== 主类 ====================
public class Demo {
    public static void main(String[] args) {
        GameBase gameBase = GameBase.createGameBase(10, 10);
        if (gameBase.getHealth() == 500) System.out.println("ok1");

        Barrack barrack = (Barrack) gameBase.building(EnumObjectType.barrack, 20, 20);
        if (barrack.getHealth() == 100) System.out.println("ok2");

        WarFactory warFactory = (WarFactory) gameBase.building(EnumObjectType.warFactory, 30, 30);
        if (warFactory.getHealth() == 100) System.out.println("ok3");

        RifleSoldier rifleSoldier1 = (RifleSoldier) barrack.train(EnumObjectType.rifleSoldier);
        if (rifleSoldier1.getHealth() == 50) System.out.println("ok4");

        RPGSoldier rPGSoldier1 = (RPGSoldier) barrack.train(EnumObjectType.RPGSoldier);
        if (rPGSoldier1.getHealth() == 50) System.out.println("ok5");

        Dog dog1 = (Dog) barrack.train(EnumObjectType.dog);
        if (dog1.getHealth() == 50) System.out.println("ok6");

        rPGSoldier1.move(10, 10);
        rifleSoldier1.attack(rPGSoldier1);
        if (rPGSoldier1.getHealth() == 50) System.out.println("ok7");

        rifleSoldier1.move(7, 6);
        rifleSoldier1.attack(rPGSoldier1);
        if (rPGSoldier1.getHealth() == 45) System.out.println("ok8");

        dog1.attack(rPGSoldier1);
        if (rPGSoldier1.getHealth() == 45) System.out.println("ok9");

        dog1.move(10, 10);
        rPGSoldier1.attack(dog1);
        if (dog1.getHealth() == 40) System.out.println("ok10");

        dog1.attack(rPGSoldier1);
        dog1.attack(rPGSoldier1);
        if (rPGSoldier1.isDestroyed()) System.out.println("ok11");

        rifleSoldier1.attack(dog1);
        if (dog1.isDestroyed()) System.out.println("ok12");

        if (Soldier.getDeadedSoldierCount() == 1) System.out.println("ok13");
        if (Soldier.getLivingSoldierCount() == 1) System.out.println("ok14");
        if (gameBase instanceof GameObject) System.out.println("ok15");
        if (rifleSoldier1 instanceof GameObject) System.out.println("ok16");
