        if (isDestroyed() && !counted) {
            rifleSoldierLivingCount--;
            rifleSoldierDeadedCount++;
            counted = true;
        }
    }
}

// 火箭兵：又一套...
class RPGSoldier extends Soldier {
    private static int rpgSoldierLivingCount = 0;  // 重复！
    private static int rpgSoldierDeadedCount = 0;  // 重复！
    // ... 完全相同的模式，代码复制粘贴
}

// 军犬：再来一套...
class Dog extends Soldier {
    private static int dogLivingCount = 0;  // 重复！
    private static int dogDeadedCount = 0;  // 重复！
    // ... 又是相同的代码
}
