```java

import java.io.*;
import java.net.*;

/**
 * 一个 HTTPServer的例子
 * 
 * @author Administrator
 *
 */
public class Demo {

	public static void main(String args[]) {
		int port;
		ServerSocket serverSocket;

		try {
